import assert from 'node:assert/strict';import {pathToFileURL,fileURLToPath} from 'node:url';import path from 'node:path';
const root=path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../../..');const dist=process.env.FORKLAUNCH_TEST_BETTER_AUTH_DEPENDENCIES+'/node_modules/better-auth/dist/';
const {betterAuthReference}=await import(pathToFileURL(root+'/cli/tests/fixtures/rust_better_auth_reference.mjs'));const {betterAuth}=await import(pathToFileURL(dist+'index.mjs'));const {twoFactor}=await import(pathToFileURL(dist+'plugins/two-factor/index.mjs'));
const originalError=console.error;console.error=()=>{};const observations=[];const password='owned-factor-password';
async function setup(){const ref=await betterAuthReference(root);ref.database.twoFactor=[];let encrypt=async s=>'X'+s,decrypt=async s=>s.slice(1),codes=['one','two'];const codec={encrypt:s=>encrypt(s),decrypt:s=>decrypt(s)};const auth=betterAuth({...ref.config,secret:'owned-backup-async-secret-at-least32',plugins:[...ref.config.plugins,twoFactor({skipVerificationOnEnable:true,backupCodeOptions:{storeBackupCodes:codec,customBackupCodesGenerate:()=>codes}})],logger:{disabled:true},rateLimit:{enabled:false}});const jar=new Map();async function call(route,body={},cookies=jar){const response=await auth.handler(new Request('http://localhost:3000/api/auth'+route,{method:'POST',headers:{origin:'http://localhost:3000','content-type':'application/json',cookie:[...cookies].map(([k,v])=>`${k}=${v}`).join('; ')},body:JSON.stringify(body)}));for(const c of response.headers.getSetCookie()){const p=c.split(';')[0],i=p.indexOf('=');if(c.includes('Max-Age=0'))cookies.delete(p.slice(0,i));else cookies.set(p.slice(0,i),p.slice(i+1));}const text=await response.text();return{status:response.status,body:text?JSON.parse(text):null};}assert.equal((await call('/sign-up/email',{name:'Backup',firstName:'Backup',lastName:'User',email:'backup-async@example.test',password})).status,200);return{ref,jar,call,setEncrypt:f=>encrypt=f,setDecrypt:f=>decrypt=f,setCodes:c=>codes=c,field:()=>ref.database.twoFactor[0]?.backupCodes,attempts:()=>ref.database.verification.filter(r=>r.identifier.startsWith('2fa-attempts-')).map(r=>r.value),enroll:()=>call('/two-factor/enable',{password}),pending:async()=>{await call('/sign-out');assert.equal((await call('/sign-in/email',{email:'backup-async@example.test',password})).body.twoFactorRedirect,true);}};}
function gate(){let entered,release;const ready=new Promise(r=>entered=r),wait=new Promise(r=>release=r);return{ready,release,run:async x=>{entered();await wait;return x;}};}
for(const kind of ['decrypt','encrypt']){const s=await setup();await s.enroll();await s.pending();const field=s.field();s[kind==='encrypt'?'setEncrypt':'setDecrypt'](async()=>{throw Error('owned failure')});assert.equal((await s.call('/two-factor/verify-backup-code',{code:'one'})).status,500);assert.equal(s.field(),field);assert.deepEqual(s.attempts(),kind==='decrypt'?['0']:[]);s.setDecrypt(async x=>x.slice(1));s.setEncrypt(async x=>'X'+x);const retry=await s.call('/two-factor/verify-backup-code',{code:'one'});assert.equal(retry.status,kind==='decrypt'?200:401);observations.push({kind,failure:500,preserved:true,attempts:kind==='decrypt'?'restored':'consumed',retry:retry.status});}
for(const text of ['not json','{}']){const s=await setup();await s.enroll();await s.pending();s.setDecrypt(async()=>text);const result=await s.call('/two-factor/verify-backup-code',{code:'one'});assert.equal(result.status,text==='{}'?500:401);assert.deepEqual(s.attempts(),text==='{}'?['0']:['1']);observations.push({decoded:text,status:result.status,attempts:s.attempts()});}
for(const event of ['signout','regenerate','disable','delete-challenge']){const s=await setup();await s.enroll();const old=s.field();const hold=gate();s.setDecrypt(async x=>(await hold.run(x)).slice(1));if(event==='delete-challenge')await s.pending();const pending=s.call('/two-factor/verify-backup-code',{code:'one'});await hold.ready;
 if(event==='signout')await s.call('/sign-out');if(event==='regenerate'){s.setCodes(['replacement']);await s.call('/two-factor/generate-backup-codes',{password});}if(event==='disable')await s.call('/two-factor/disable',{password});if(event==='delete-challenge')s.ref.database.verification=s.ref.database.verification.filter(r=>!r.identifier.startsWith('2fa-')||r.identifier.startsWith('2fa-attempts-'));
 hold.release();const result=await pending;const expected=event==='signout'?200:event==='delete-challenge'?401:409;assert.equal(result.status,expected);if(event==='signout'||event==='delete-challenge')assert.equal(s.field(),'X["two"]');if(event==='regenerate')assert.equal(s.field(),'X["replacement"]');if(event==='disable')assert.equal(s.field(),undefined);observations.push({duringDecrypt:event,status:result.status,field:s.field()??null,oldField:old});}
for(const route of ['enable','generate-backup-codes']){const s=await setup();if(route!=='enable')await s.enroll();const hold=gate();s.setEncrypt(async x=>'X'+await hold.run(x));s.setCodes(['fresh']);const pending=s.call('/two-factor/'+route,{password});await hold.ready;await s.call('/sign-out');hold.release();const result=await pending;assert.equal(result.status,200);assert.equal(s.field(),'X["fresh"]');observations.push({duringEncrypt:route,signout:'does-not-recheck',status:200});}
{
 const s=await setup();await s.enroll();let entered=0,release,ready;const both=new Promise(r=>ready=r),wait=new Promise(r=>release=r);s.setDecrypt(async x=>{if(++entered===2)ready();await wait;return x.slice(1)});const a=s.call('/two-factor/verify-backup-code',{code:'one'},new Map(s.jar));const b=s.call('/two-factor/verify-backup-code',{code:'one'},new Map(s.jar));await both;release();const results=await Promise.all([a,b]);assert.deepEqual(results.map(r=>r.status).sort(),[200,409]);assert.equal(s.field(),'X["two"]');observations.push({concurrentConsume:[200,409],field:s.field()});
}
{
 const s=await setup();await s.enroll();const hold=gate();let first=true;s.setEncrypt(async x=>{if(first){first=false;await hold.run(x);}return 'X'+x;});const pending=s.call('/two-factor/generate-backup-codes',{password},new Map(s.jar));await hold.ready;assert.equal((await s.call('/two-factor/verify-backup-code',{code:'one'})).status,200);assert.equal(s.field(),'X["two"]');hold.release();assert.equal((await pending).status,200);assert.equal(s.field(),'X["one","two"]');observations.push({regenerateAfterConsume:'unconditional-overwrites',reissuedFixedGeneratorCode:true});
}
console.error=originalError;console.log('PASS actual async backup audit',JSON.stringify(observations));
